'use strict';
const projects = window.DELIVERABLES || [];
const app = document.querySelector('#app');
const filename = location.pathname.split('/').pop() || 'index.html';
const project = projects.find(p => p.id === filename.replace('.html', ''));
const escapeHTML = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const picture = (url,title) => `<button type="button" data-image="${url}" data-title="${escapeHTML(title)}" aria-label="放大查看 ${escapeHTML(title)}"><img src="${url}" alt="${escapeHTML(title)}" loading="lazy"></button>`;
const state = p => p.status==='review'?'首轮概念 · 待评审':'已交付';
function renderHome(){
 document.title='废土造物 — 制品交付档案';
 app.innerHTML=`<section class="hero"><div class="eyebrow">GAME ART / DELIVERY ARCHIVE</div><span class="hero-index">Field notes. 001</span><h1>从一次探索，<br>到一套<em>造物语言。</em></h1><div class="hero-bottom"><p>为 Roblox 生存游戏构建可辨识的废土制品。<br>从原素材配对、风格探索，到单件三视图与反馈修订。</p><div class="stats"><div class="stat"><b>${String(projects.length).padStart(2,'0')}</b><span>制品分组</span></div><div class="stat"><b>${projects.reduce((n,p)=>n+p.count,0)}</b><span>制品设计</span></div><div class="stat"><b>83</b><span>本轮素材配对</span></div></div></div></section><section><div class="section-head"><h2>制品档案 <span>DELIVERABLES</span></h2><p>成品图片 / 原素材配对 / 制作记录</p></div><div class="delivery-grid">${projects.map(p=>`<a class="delivery-card" href="${p.id}.html"><div class="card-picture"><img src="${p.overview}" alt="${p.name}总览" loading="lazy"><div class="picture-meta"><span class="tag"><i></i>${state(p)} · ${p.latest.toUpperCase()}</span><span class="tag">${p.english}</span></div><span class="card-arrow">↗</span></div><div class="card-info"><div><h3><small>${p.number}</small>${p.name}</h3><p>${p.summary}</p></div><div class="card-count">${p.count}<span>件设计 · ${p.iterations} 个版本</span></div></div></a>`).join('')}</div></section><section class="principles"><h2>不同的科技，<br>同一套<em>视觉语言。</em></h2><div class="principle-grid"><article><span>01 /</span><h3>尺度服从用途</h3><p>设施统一占地，道具统一握持与穿戴尺度，动物保留生态体型。</p></article><article><span>02 /</span><h3>递进有据可查</h3><p>同支线通过结构和性能升级；活动、调试与生态侧支单独标注。</p></article><article><span>03 /</span><h3>过程可追溯</h3><p>保留原素材、设定出处、转译决定和图像版本，便于继续评审。</p></article></div></section>`;
}
function mappingTable(p){return `<section id="mapping"><div class="section-head"><h2>替换对应 <span>SOURCE MAPPING</span></h2><p>序位只在同一支线内比较；0 为调试项。</p></div><div class="table-scroll"><table class="mapping-table"><thead><tr><th>编号 / 原素材</th><th>废土制品</th><th>支线 / 序位</th><th>来源 / 状态</th><th>改编与玩法衔接</th></tr></thead><tbody>${p.items.map(i=>`<tr><td>${i.tier}<small>${escapeHTML(i.original)}<br>${escapeHTML(i.features)}</small></td><td>${i.name}</td><td>${i.branch}<small>序位 ${i.rank}</small></td><td>${i.source}<small>${i.status} · ${i.priority}</small></td><td>${escapeHTML(i.description)}</td></tr>`).join('')}</tbody></table></div><p class="compare-note">设定编号 A：动物；C：冷兵器；G：枪械；F：食物；E：个人装备。完整原文摘录见本组输入表。改编项为本轮设计决定，不代表原设定已有这些功能。</p></section>`;}
function renderProject(p){
 document.title=`${p.name} · 成品与迭代 — 废土造物`;
 const mapped=p.status==='review';
 const next=projects[(projects.indexOf(p)+1)%projects.length];
 app.innerHTML=`<div class="breadcrumb"><a href="index.html">交付总览</a><span>/</span><span>${p.name}</span></div><section class="project-hero"><div class="eyebrow">${p.english} / DELIVERY ${p.number}</div><h1><small>${p.number}</small>${p.name}</h1><div class="project-subtitle"><p>${p.summary}</p><div class="project-tags"><span class="tag dark">${state(p)} · ${p.latest.toUpperCase()}</span><span class="tag">${p.count} 件制品</span><span class="tag">${p.iterations} 个版本</span></div></div></section><div class="project-tabs"><nav aria-label="页面章节"><a href="#final">${mapped?'首轮图片':'最终成品'}</a>${mapped?'<a href="#mapping">替换对应</a>':''}<a href="#iterations">制作过程</a><a href="#compare">版本对比</a><a href="#documents">设计资料</a></nav></div><section id="final"><div class="overview-image">${picture(p.overview,`${p.name} · ${p.latest} 风格总览`)}<span class="zoom-hint">↗ 点击查看大图</span></div><div class="image-caption"><span>COLLECTION / ${p.latest.toUpperCase()}</span><a class="download" href="${p.overview}" download>下载总览 ↓</a></div>${mapped?'<p class="compare-note">上图是前置风格母图，按原素材顺序排布。当前造型以以下单件图为准；功能递进请结合支线与序位查看。</p>':''}<div class="project-tags">${p.standards.map(s=>`<span class="tag">${s}</span>`).join('')}</div><div class="section-head"><h2>单件设计 <span>ASSET SHEETS</span></h2><p>${p.views||'斜前视 / 侧视 / 俯视'}</p></div>${mapped?`<div class="asset-filters"><label>查找素材<input id="asset-search" type="search" placeholder="编号、原名、新名称"></label><label>功能支线<select id="asset-branch"><option value="">全部支线</option>${[...new Set(p.items.map(i=>i.branch))].map(b=>`<option>${b}</option>`).join('')}</select></label><span id="asset-count" aria-live="polite">${p.count} 件</span></div>`:''}<div class="grade-grid" id="asset-gallery"></div></section>${mapped?mappingTable(p):''}<section id="iterations"><div class="section-head"><h2>制作过程 <span>DESIGN ITERATIONS</span></h2><p>${mapped?'首轮：配对 → 输入表 → 风格母图 → 单件三视图':'每一轮变化，都有一个理由。'}</p></div><div class="iteration-layout"><div class="version-nav" role="group" aria-label="选择迭代版本">${[...p.versions].reverse().map(v=>`<button class="version-btn ${v.id===p.latest?'active':''}" data-version="${v.id}" aria-pressed="${v.id===p.latest}"><b>${v.id.toUpperCase()}</b><span>${v.title}</span></button>`).join('')}</div><div class="version-panel" id="version-panel" aria-live="polite"></div></div></section><section id="compare"><div class="section-head"><h2>前后对比 <span>SIDE BY SIDE</span></h2><p>查看同一件制品的版本变化。</p></div>${mapped?'<div class="missing">本组为首轮 v1，暂无第二轮图片。风格母图与单件三视图属于本轮制作阶段，未作为两次修订版本。后续评审后在这里追加真实版本对比。</div>':`<div class="compare-layout"><div class="compare-controls"><label for="compare-tier">制品</label><select id="compare-tier">${p.items.map((i,n)=>`<option value="${n}">${i.tier} ${i.name}</option>`).join('')}</select><span class="compare-spacer"></span><label for="compare-from">从</label><select id="compare-from"></select><label for="compare-to">到</label><select id="compare-to"></select></div><div class="compare-pair" id="compare-pair"></div><p class="compare-note">各版本保留原始构图与比例，便于观察造型变化。</p></div>`}</section><section id="documents"><div class="section-head"><h2>设计资料 <span>REFERENCE FILES</span></h2><p>输入表、来源、提示词与原图归档。</p></div><div class="document-list">${p.documents.map(d=>`<a href="${d.url}" download>${d.name}<span>${d.url.endsWith('.zip')?'ZIP':'MD'} ↓</span></a>`).join('')}</div></section><a class="next-project" href="${next.id}.html"><div><small>NEXT DELIVERY / ${next.number}</small><strong>继续查看 · ${next.name}</strong></div><span>↗</span></a>`;
 renderGallery(p);
 if(mapped){for(const id of ['#asset-search','#asset-branch'])document.querySelector(id).addEventListener(id.includes('search')?'input':'change',()=>renderGallery(p));}
 renderVersion(p,p.latest);renderFixes(p);
 document.querySelectorAll('[data-version]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-version]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});renderVersion(p,button.dataset.version);renderFixes(p);}));
 if(!mapped){document.querySelector('#compare-tier').addEventListener('change',()=>updateCompareOptions(p));document.querySelector('#compare-from').addEventListener('change',()=>renderCompare(p));document.querySelector('#compare-to').addEventListener('change',()=>renderCompare(p));updateCompareOptions(p);}
}
function renderGallery(p){
 const mapped=p.status==='review';
 const search=mapped?(document.querySelector('#asset-search').value||'').toLowerCase().trim():'';
 const branch=mapped?document.querySelector('#asset-branch').value:'';
 const items=p.items.filter(i=>(!branch||i.branch===branch)&&[i.tier,i.name,i.original||''].join(' ').toLowerCase().includes(search));
 document.querySelector('#asset-gallery').innerHTML=items.map(i=>`<article class="grade-card">${picture(i.images[p.latest],`${i.tier} ${i.name} · ${p.latest}`)}<div class="grade-body"><div class="grade-head"><h3><span>${i.tier}</span>${i.name}</h3><a class="download" href="${i.images[p.latest]}" download>下载三视图 ↓</a></div>${mapped?`<div class="asset-meta">${escapeHTML(i.original)} → ${i.name}<br>${i.branch} · 序位 ${i.rank} · ${i.source}</div>`:''}<p>${escapeHTML(i.description)}</p></div></article>`).join('')||'<p>没有匹配的制品。</p>';
 if(mapped)document.querySelector('#asset-count').textContent=`${items.length} / ${p.count} 件`;
}
function renderVersion(p,id){const v=p.versions.find(v=>v.id===id);document.querySelector('#version-panel').innerHTML=`<header><h3><em>${id.toUpperCase()}</em>${v.title}</h3>${id===p.latest?'<span class="version-status">最新展示版本</span>':''}</header><div class="change-notes"><div><h4>本轮调整 / CHANGE</h4><p>${v.change}</p></div><div><h4>调整原因 / WHY</h4><p>${v.reason}</p></div><div><h4>阶段结果 / OUTCOME</h4><p>${v.outcome}</p></div></div>${p.status==='review'?`<div class="history-card">${picture(p.overview,p.name+' 风格母图')}<span>制作阶段 01 / 组内风格与轮廓母图</span></div><p class="compare-note">制作阶段 02 / 引用母图逐件扩展，完整单件图见上方图库。</p>`:`<div class="history-grid">${p.items.map(i=>i.images[id]?`<div class="history-card">${picture(i.images[id],`${i.tier} ${i.name} · ${id}`)}<span>${i.tier} / ${i.name}</span></div>`:`<div class="missing">${i.tier} ${i.name}<br>本轮未重绘，沿用此前版本。</div>`).join('')}</div>`}`;}
function renderFixes(p){if(!p.fixes?.length)return;document.querySelector('#version-panel').innerHTML+=p.fixes.map(f=>`<h3>${f.title}</h3><p class="compare-note">${f.reason}</p><div class="compare-pair"><div class="compare-cell">${picture(f.before,f.title+' 初稿')}<p>本轮初稿</p></div><div class="compare-cell">${picture(f.after,f.title+' 修正')}<p>本轮修正 · 当前单件图</p></div></div>`).join('');}
function updateCompareOptions(p){const item=p.items[Number(document.querySelector('#compare-tier').value)];const versions=p.versions.filter(v=>item.images[v.id]);for(const id of ['compare-from','compare-to'])document.getElementById(id).innerHTML=versions.map(v=>`<option value="${v.id}">${v.id.toUpperCase()}</option>`).join('');document.querySelector('#compare-from').value=versions[0].id;document.querySelector('#compare-to').value=versions[versions.length-1].id;renderCompare(p);}
function renderCompare(p){const item=p.items[Number(document.querySelector('#compare-tier').value)];document.querySelector('#compare-pair').innerHTML=['compare-from','compare-to'].map(id=>{const version=document.getElementById(id).value;const v=p.versions.find(v=>v.id===version);return `<div class="compare-cell">${picture(item.images[version],`${item.tier} ${item.name} · ${version}`)}<p><b>${version.toUpperCase()} / ${v.title}</b><a class="download" href="${item.images[version]}" download>下载 ↓</a></p></div>`;}).join('');}
document.querySelector('.header nav').innerHTML=`<a href="index.html" data-nav="home">总览</a>${projects.map(p=>`<a href="${p.id}.html" data-nav="${p.id}">${p.name}</a>`).join('')}`;
if(project)renderProject(project);else renderHome();
document.querySelector(`[data-nav="${project?project.id:'home'}"]`)?.classList.add('active');
const dialog=document.querySelector('#viewer');let previousFocus;
document.addEventListener('click',event=>{const trigger=event.target.closest('[data-image]');if(!trigger)return;previousFocus=trigger;const image=document.querySelector('#viewer-image');image.src=trigger.dataset.image;image.alt=trigger.dataset.title;document.querySelector('#viewer-title').textContent=trigger.dataset.title;document.querySelector('#viewer-download').href=trigger.dataset.image;dialog.showModal();document.body.style.overflow='hidden';});
document.querySelector('#close-viewer').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
dialog.addEventListener('close',()=>{document.body.style.overflow='';previousFocus?.focus();});
